// spec: specs/placement-reading.md (2.6) · кейс PRD-09 · запасной путь (WebKit 390 через test.use на уровне файла)
// seed: tests/seed.parent.spec.ts
// Тег @data отправляет тест в проект data (десктоп Chrome), поэтому устройство задано здесь: iPhone 390×844, WebKit.
// Окно — встроенный page с test.use (фикстура asUser берёт параметры окна из проекта, а не из test.use).
import * as path from 'path';
import { devices } from '@playwright/test';
import { test, expect } from '../../fixtures';
import {
  annotateCleanup,
  createChild,
  expectInsideViewport,
  expectNoHorizontalScroll,
  handoverToIntro,
  passReadingToResults,
  qaChildName,
  readingScreens,
} from './reading.helpers';


// Пропущено 08.11 (решение пользователя): тест создаёт нового ребёнка QA-AUTO и передаёт ему устройство — с #8ca267 режим ребёнка серверный и запирает вход до ввода пароля/PIN.
test.skip(true, 'QA-AUTO + режим ребёнка запирает вход (#8ca267) — пропущено по решению 08.11');

test.use({
  browserName: 'webkit',
  viewport: { width: 390, height: 844 },
  isMobile: true,
  hasTouch: true,
  deviceScaleFactor: 3,
  userAgent: devices['iPhone 13'].userAgent,
  storageState: path.resolve(__dirname, '../../../auth/parent.json'),
});

test.describe('Стартовый тест чтения — одна попытка, продолжение, сбои, 390 (autotest-writer)', () => {
  test('390 (iPhone, WebKit): C1, C2, C3 без горизонтальной прокрутки @iphone @data #8bf5a8', async ({ page }, testInfo) => {
    test.setTimeout(5 * 60_000); // лимит на 3 отрывка, не пауза
    const s = readingScreens(page);
    const name = qaChildName();

    // 1. Создать ребёнка, передать устройство → C1
    const childId = await createChild(page, name, '2018');
    annotateCleanup(testInfo, name, childId);
    await handoverToIntro(page, childId, name);

    // C1: без горизонтальной прокрутки, «מתחילים!» в пределах 390 (AC5; решение 28.10)
    await expectNoHorizontalScroll(page, 'C1');
    await expectInsideViewport(page, s.start, 'C1 «מתחילים!»');

    // 2. «מתחילים!» → C2, отрывок 1
    await s.start.click();
    await expect(s.passage(1)).toBeVisible();
    await expect(s.read).toBeVisible();
    await expectNoHorizontalScroll(page, 'C2 (קטע 1)');

    // 3. Пройти 3 отрывка самооценкой до C3
    await passReadingToResults(page, 'בסדר');
    await expect(s.resultsTitle).toBeVisible();
    await expectNoHorizontalScroll(page, 'C3');
    await expectInsideViewport(page, s.resultsStart, 'C3 «יאללה, מתחילים!»');
  });
});
